async function fnLoadHQTexture(data) {

    if (!data) return;

    const material = data.mesh.material;
    const name = data.name;
    //let textureIsLoaded = data.textureIsLoaded;
    if (!data.hqTexture) {
        const textureDiffuse = await modelLoader.loadKTX2Texture(`./assets/models/${name}/base_color_cmp.ktx2`);

        if (material.uniforms && material.uniforms.uDiffuseMap !== undefined) {
            material.uniforms.uDiffuseMap.value.dispose();
            material.uniforms.uDiffuseMap.value = textureDiffuse;
        } else {
            material.map = textureDiffuse;
        }


        data.hqTexture = textureDiffuse;
    } else {
        material.uniforms.uDiffuseMap.value = data.hqTexture;
    }
    //data.mesh.material.needsUpdate = true;
}


