/********************************************************************
// Worker Pool for Grass Generation
********************************************************************/
const workerPoolSize = navigator.hardwareConcurrency || 4; // Number of workers based on CPU cores
const grassWorkerPool = [];
const grassWorkerQueue = []; // Queue for pending tasks

// Initialize the worker pool
for (let i = 0; i < workerPoolSize; i++) {
    const worker = new Worker(new URL('grassWorker.js', import.meta.url), { type: 'module' });
    worker.onmessage = (event) => {
        requestIdleCallback(() => {


            const { chunkKey, grassGeometryData } = event.data;
            //console.log(event.data)
            // Create instanced buffer geometry for grass blades
            const grassGeometry = new THREE.InstancedBufferGeometry();

            //grassGeometry.copy(new THREE.PlaneGeometry(5, 5)); // Base blade geometry
            grassGeometry.copy(bladeGeometry);

            grassGeometry.setAttribute('instanceRotationMatrix', new THREE.InstancedBufferAttribute(grassGeometryData.rotationMatrices, 9));
            grassGeometry.setAttribute('scale', new THREE.InstancedBufferAttribute(grassGeometryData.scales, 1));
            grassGeometry.setAttribute('uv', new THREE.InstancedBufferAttribute(grassGeometryData.uvs, 2));

            //grassGeometry.computeVertexNormals();

            //calc the y-value using GetHeight()

            for (let i = 0; i < grassGeometryData.instanceCount; i++) {
                grassGeometryData.offsets[i * 3 + 1] = getHeight(grassGeometryData.offsets[i * 3], grassGeometryData.offsets[i * 3 + 2]) - 0.60; // Calculate height using getHeight
            }


            grassGeometry.setAttribute('offset', new THREE.InstancedBufferAttribute(grassGeometryData.offsets, 3));

            //const grassMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00, side: THREE.DoubleSide });
            const grassMesh = new THREE.InstancedMesh(grassGeometry, grassMaterial, grassGeometryData.instanceCount);
            //grassMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

            // Set the bounding box for the grass mesh to match the chunk size
            //grassMesh.computeBoundingSphere();
            grassMesh.geometry.boundingSphere = grassGeometryData.boundingSphere;
            grassMesh.material.envMap = envMap;
            grassMesh.material.envMapIntensity = 0.25;


            // Add grass to the scene
            worldScene.scene.add(grassMesh);


            // Store the grass mesh in the loadedChunks map
            if (loadedChunks.has(chunkKey)) {
                loadedChunks.get(chunkKey).grassMesh = grassMesh;
            }

            // Process the next task in the queue, if any
            if (grassWorkerQueue.length > 0) {
                const nextTask = grassWorkerQueue.shift();
                worker.postMessage(nextTask);

            } else {
                grassWorkerPool.push(worker); // Return worker to the pool
                //fnOnTerrainComplete(); //and models have loaded, maybe set flag for terrain complete here
                allGrassComputed = true;
            }

        });
    };

    grassWorkerPool.push(worker);
}


function postToGrassWorker(task) {
    if (grassWorkerPool.length > 0) {
        const worker = grassWorkerPool.pop();
        worker.postMessage(task);
    } else {
        grassWorkerQueue.push(task); // Add task to the queue if no worker is available
    }
}






