const groundMaterial = new THREE.MeshBasicMaterial({
    color: 0x00000 // Use the specified material color

    //flatShading: chunkProps.type === "ground", // Enable flat shading for ground-only chunks
});


function fnGenerateChunk(x, z) {
    const offsetX = x * chunkSize;
    const offsetZ = z * chunkSize;

    const chunkKey = `${x},${z}`;
    const isSpecialChunk = specialChunks.hasOwnProperty(chunkKey);


    // Define chunk properties based on whether it's a special chunk or not
    const chunkProps = isSpecialChunk
        ? specialChunks[chunkKey]
        : { type: "default", materialColor: 0x000000, grassBladeCount: instanceCount };

    // Create geometry for the terrain chunk
    const baseGeometry = new THREE.PlaneGeometry(chunkSize, chunkSize, chunkVertexCount, chunkVertexCount);
    baseGeometry.rotateX(-Math.PI / 2);

    // Adjust the geometry's position so that its origin aligns with the top-left corner
    baseGeometry.translate(chunkSize / 2, 0, chunkSize / 2);

    const chunkBoundingSphere = new THREE.Sphere(
        new THREE.Vector3(chunkSize, 0.0, chunkSize),
        chunkSize * 1.5
    );

    baseGeometry.boundingSphere = chunkBoundingSphere;

    const geometry = baseGeometry.clone();

    // Modify the vertices based on simplex noise
    const vertices = geometry.attributes.position.array;

    for (let i = 0; i < vertices.length; i += 3) {
        const vertexX = vertices[i] + offsetX;
        const vertexZ = vertices[i + 2] + offsetZ;
        vertices[i + 1] = getHeight(vertexX, vertexZ); // Set Y position based on height
    }
    //geometry.computeVertexNormals(); // Recalculate normals for smooth shading

    // Create the mesh
    const chunkMesh = new THREE.Mesh(geometry, groundMaterial);
    chunkMesh.position.set(offsetX, 0, offsetZ);

    //if (Utils.fnIsInFrustum(chunkMesh, camera)) {
    //console.log("Is in Frustrum");
    //requestIdleCallback(() => {
    postToGrassWorker({ chunkKey, offsetX, offsetZ, chunkSize, instanceCount: chunkProps.grassBladeCount });
    //});
    //}

    // Add grass if the chunk has grassBladeCount > 0
    //if (chunkProps.grassBladeCount !== undefined && chunkProps.grassBladeCount > 0) {

    //}
    //console.log(chunkMesh)

    return chunkMesh;
}


/********************************************************************
// Load Initial Terrain
********************************************************************/
function loadInitialTerrain(sizeInChunks) {

    totalChunks = sizeInChunks * sizeInChunks;

    for (let z = 0; z < sizeInChunks; z++) {
        for (let x = 0; x < sizeInChunks; x++) {
            const chunkKey = `${x},${z}`;
            if (!loadedChunks.has(chunkKey)) {
                const chunkMesh = fnGenerateChunk(x, z);
                worldScene.scene.add(chunkMesh);
                loadedChunks.set(chunkKey, { terrainMesh: chunkMesh });
            }
        }
    }
}

